using Catalogo.Api.Data; using Microsoft.EntityFrameworkCore; using Microsoft.OpenApi;
var builder=WebApplication.CreateBuilder(args); builder.Services.AddControllers(); builder.Services.AddDbContext<CatalogoDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("CatalogoConnection"))); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(o=>o.SwaggerDoc("v1",new OpenApiInfo{Title="Catalogo.Api",Version="v1"})); builder.Services.AddCors(o=>o.AddPolicy("LocalSwagger",policy=>policy.WithOrigins("http://localhost:5149").AllowAnyHeader().AllowAnyMethod())); var app=builder.Build(); app.UseCors("LocalSwagger"); if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();} app.MapGet("/health",()=>Results.Ok(new{servicio="Catalogo.Api",estado="activo"})); app.MapControllers(); app.Run();

